,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    <strong>\30C7\30FC\30BF\30D9\30FC\30B9\64CD\4F5C</strong>\3092\3053\306EHTTP\64CD\4F5C\306B\5272\308A\5F53\3066\307E\3059\3002\30C7\30FC\30BF\30D9\30FC\30B9\64CD\4F5C\306F\3001&PRODUCT_NAME.\30B3\30F3\30DD\30FC\30CD\30F3\30C8\304CREST\30C7\30FC\30BF\30FB\30BD\30FC\30B9\3068\9023\643A\3059\308B\305F\3081\306B\91CD\8981\3067\3059\3002&PRODUCT_NAME.\30B3\30F3\30DD\30FC\30CD\30F3\30C8\306F(\64CD\4F5C\3067\306F\306A\304F) REST\30C7\30FC\30BF\30FB\30BD\30FC\30B9\306B\5272\308A\5F53\3066\3089\308C\308B\305F\3081\3001\5FC5\8981\306A\30C7\30FC\30BF\30D9\30FC\30B9\64CD\4F5C\306B\57FA\3065\3044\305FHTTP\64CD\4F5C\3092\53C2\7167\3057\307E\3059\3002'),
'</p>',
'<ul>',
unistr('    <li>\30EC\30DD\30FC\30C8\3001\30C1\30E3\30FC\30C8\3001CSS\30AB\30EC\30F3\30C0\306A\3069\306E\8996\899A\5316\30B3\30F3\30DD\30FC\30CD\30F3\30C8\306F\3001<strong>\300C\884C\306E\30D5\30A7\30C3\30C1\300D</strong>\30C7\30FC\30BF\30D9\30FC\30B9\64CD\4F5C\306B\5272\308A\5F53\3066\3089\308C\3066\3044\308BHTTP\64CD\4F5C\3092\5E38\306B\4F7F\7528\3057\307E\3059\3002<strong>APEX_EXEC.OPEN_WEB_SOURCE_QUERY</strong>\3067\3082\300C\884C\306E\30D5\30A7\30C3\30C1\300D\30C7\30FC\30BF\30D9\30FC\30B9\64CD\4F5C\304C\4F7F\7528\3055\308C\307E\3059\3002</li>'),
unistr('    <li>\30D5\30A9\30FC\30E0\30FB\30B3\30F3\30DD\30FC\30CD\30F3\30C8\3067\306F\3001\884C\3092\633F\5165\3001\66F4\65B0\307E\305F\306F\524A\9664\3059\308B\969B\306B\3001\305D\308C\305E\308C<strong>\300C\884C\306E\633F\5165\300D</strong>\3001<strong>\300C\884C\306E\66F4\65B0\300D</strong>\307E\305F\306F<strong>\300C\884C\306E\524A\9664\300D</strong>\306B\5272\308A\5F53\3066\3089\308C\3066\3044\308B\64CD\4F5C\304C\4F7F\7528\3055\308C\307E\3059\3002PL/SQL\3067\306F\3001<strong>APEX_EXEC.OPEN_WEB_SOURCE_DML_CONTEXT</strong>\306F\30D5\30A9\30FC\30E0\3068\540C\7B49\3067\3059\3002</li>'),
unistr('    <li><strong>\300C\5358\4E00\884C\306E\30D5\30A7\30C3\30C1\300D</strong>\30C7\30FC\30BF\30D9\30FC\30B9\64CD\4F5C\306F\3001\5931\308F\308C\305F\66F4\65B0\306E\691C\51FA\307E\305F\306F\5B9F\884C\53EF\80FD\306A\64CD\4F5C\306E\78BA\8A8D\304C\5B9F\884C\3055\308C\308B\3068\304D\306B\30D5\30A9\30FC\30E0\30FB\30B3\30F3\30DD\30FC\30CD\30F3\30C8\306B\3088\3063\3066\4F7F\7528\3055\308C\307E\3059\3002\30D5\30A9\30FC\30E0\3067\306F\3001\3053\306E\64CD\4F5C\3092\4F7F\7528\3057\3066\3001\5B9F\969B\306EDML\64CD\4F5C\3092\5B9F\884C\3059\308B\524D\306BREST\30B5\30FC\30D3\30B9\304B\3089\884C\304C\518D\30D5\30A7\30C3\30C1\3055\308C\307E\3059\3002</li>'),
unistr('    <li>\30C7\30FC\30BF\30D9\30FC\30B9\64CD\4F5C\306B\30DE\30C3\30D7\3055\308C\3066\3044\306A\3044\64CD\4F5C\306F\3001&PRODUCT_NAME.\30B3\30F3\30DD\30FC\30CD\30F3\30C8\306B\3088\3063\3066\4F7F\7528\3055\308C\307E\305B\3093\3002<strong>APEX_EXEC.EXECUTE_WEB_SOURCE</strong> PL/SQL\30D7\30ED\30B7\30FC\30B8\30E3\3092\4F7F\7528\3057\3066\3001\3053\308C\3089\3092PL/SQL\30B3\30F3\30C6\30AD\30B9\30C8\304B\3089\5B9F\884C\3057\307E\3059\3002</li>'),
