,p_name=>'PE.PROPERTY.INIT_POSITION_ZOOM_SOURCE_SQL.EXAMPLES'
,p_message_language=>'ja'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\30DE\30C3\30D7\306E\521D\671F\4F4D\7F6E\304A\3088\3073\30BA\30FC\30E0\30FB\30EC\30D9\30EB\3092\6C7A\5B9A\3059\308BNUMBER\5217\3092\8FD4\3059\554F\5408\305B:</p>'),
'<pre>',
'select -133.5 longitude,',
'         35.2 latitude,',
'            3 zoom',
'  from sys.dual',
'</pre>',
unistr('<p>\30DE\30C3\30D7\306E\521D\671F\4F4D\7F6E\304A\3088\3073\30BA\30FC\30E0\30FB\30EC\30D9\30EB\306ENUMBER\5217\3092\6C7A\5B9A\3059\308BSDO_GEOMETRY\5217\3092\8FD4\3059\554F\5408\305B\3002</p>'),
'<pre>',
unistr('select sdo_geometry( 2001,                                 -- 2\6B21\5143\306E\70B9'),
unistr('                     4326,                                 -- \7D4C\5EA6/\7DEF\5EA6(WGS84)'),
unistr('                     sdo_point_type( -133.5, 35.2, null ), -- \5177\4F53\7684\306A\5EA7\6A19'),
unistr('                     null,                                 -- \30DD\30A4\30F3\30C8\306B\306F\4F7F\7528\3057\306A\3044'),
unistr('                     null                                  -- \30DD\30A4\30F3\30C8\306B\306F\4F7F\7528\3057\306A\3044'),
'       )                   as geometry,',
'       3                   as zoom',
'  from sys.dual',
'</pre>'))
,p_version_scn=>2565189
);
