,p_message_language=>'ja'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\30DA\30FC\30B8\30FB\30A2\30A4\30C6\30E0\304C\9078\629E\3055\308C\305F\5834\5408\3001\30DE\30C3\30D7\30FB\30EA\30FC\30B8\30E7\30F3\306F\5E38\306B\3001\73FE\5728\306E\30DE\30C3\30D7\5883\754C\30DC\30C3\30AF\30B9\3092GeoJSON\5F62\5F0F\3067\3053\306E\30A2\30A4\30C6\30E0\306E\5024\3068\3057\3066\7DAD\6301\3057\307E\3059\3002\3053\308C\3092\884C\3046\3068\3001\30DE\30C3\30D7\3092\5225\306EAPEX\30B3\30F3\30DD\30FC\30CD\30F3\30C8(\30AF\30E9\30B7\30C3\30AF\30FB\30EC\30DD\30FC\30C8\307E\305F\306F\5BFE\8A71\30E2\30FC\30C9\30FB\30EC\30DD\30FC\30C8\306A\3069)\306B\63A5\7D9A\3059\308B\969B\306B\5F79\7ACB\3061\307E\3059: \5883\754C\30DC\30C3\30AF\30B9\30FB\30A2\30A4\30C6\30E0\306E\30B3\30F3\30C6\30F3\30C4\306F\3001\4ED6\306E\30B3\30F3\30DD\30FC\30CD\30F3\30C8\304C\7A7A\9593\554F\5408\305B\3092\5B9F\884C\3057\3001\30DE\30C3\30D7\306B\8868\793A\3055\308C\3066\3044\308B\30C7\30FC\30BF\306E\307F\3092\8868\793A\3059\308B\305F\3081\306B\4F7F\7528\3067\304D\307E\3059\3002</p>'),
unistr('<p>\30DE\30C3\30D7\306E\79FB\52D5\307E\305F\306F\30BA\30FC\30E0\30FB\30EC\30D9\30EB\306E\5909\66F4\5F8C\306E\5883\754C\30DC\30C3\30AF\30B9\30FB\30A2\30A4\30C6\30E0\306E\30B3\30F3\30C6\30F3\30C4\306E\4F8B:</p>'),
'<pre>',
'{',
'  "type": "Polygon",',
'  "coordinates": [[',
'                    [-5.499,46.380],',
'                    [ 8.187,46.380],',
'                    [ 8.187,49.550],',
'                    [-5.499,49.550],',
'                    [-5.499,46.380]]]',
'}',
'</pre>',
'<p>',
unistr('\300C\52D5\7684\30A2\30AF\30B7\30E7\30F3\306E<strong>\30EA\30D5\30EC\30C3\30B7\30E5</strong>\300D\3092\4F7F\7528\3057\3066\3001\30DE\30C3\30D7\3092\30EC\30DD\30FC\30C8\30FB\30EA\30FC\30B8\30E7\30F3\306B\63A5\7D9A\3067\304D\307E\3059\3002\30EC\30DD\30FC\30C8\30FB\30EA\30FC\30B8\30E7\30F3\306F\3001\7A7A\9593\30D5\30A3\30EB\30BF\3092\9069\7528\3057\3066\3001\30DE\30C3\30D7\306B\3082\8868\793A\3055\308C\308B\7D50\679C\306E\307F\3092\8868\793A\3067\304D\307E\3059\3002</p>'),
unistr('<p>\30EC\30DD\30FC\30C8\554F\5408\305B\306E\4F8B:</p>'),
'<pre>',
'select [column1],',
'       [column2],',
'       ...',
'  from ...',
' where sdo_anyinteract(',
'           [geometry-column],',
'           sdo_util.from_geojson( :[item-name-of-bounding-box-item] )',
