,p_name=>'PE.PROPERTY.SHORTCUT_JS_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'ja'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>\5F93\696D\54E1\304C\90E8\958030\306B\6240\5C5E\3059\308B\5834\5408\3001YES\3092\8FD4\3057\307E\3059\3002</dt>'),
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 ? "YES" : "NO" );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2565108
);
