,p_name=>'PE.PROPERTY.SHORTCUT_PLSQL_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'ja'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>\5F93\696D\54E1\304C\90E8\958030\306B\6240\5C5E\3059\308B\5834\5408\3001YES\3092\8FD4\3057\307E\3059\3002</dt>'),
'<dd><pre>',
'declare',
'    l_deptno number;',
'begin',
'    select deptno',
'      into l_deptno',
'      from emp',
'     where empno = :P2_EMPNO;',
'',
'    if l_deptno = 30 then',
'        return ''YES'';',
'    else',
'        return ''NO'';',
'    end if;',
'end;',
'</pre></dd>',
'</dl>'))
