'',
unistr('<dl><dt>\3059\3079\3066\306E\5F93\696D\54E1\540D\3068\305D\306E\8077\52D9\306E\30EA\30B9\30C8\3092\51FA\529B\3057\307E\3059:</dt>'),
'<dd><pre>',
'declare',
'    l_result clob := ''&lt;h4>List of employees:&lt;/h4&gt;'';',
'begin',
'    l_result := l_result || ''&lt;ul&gt;'';',
'    for l_emp in ( select ename,',
'                          job',
'                     from emp',
'                    order by ename )',
'    loop',
'        l_result := l_result ||',
'                    ''&lt;li&gt;&lt;strong&gt;'' || apex_escape.html( l_emp.ename ) || ''&lt;/strong&gt;'' ||',
'                    '' ('' || apex_escape.html( l_emp.job ) || '')&lt;/li&gt;'';',
'    end loop;',
'    l_result := l_result || ''&lt;/ul&gt;'';',
'',
'    return l_result;',
'end;',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2565108
);
