,p_return_value=>'APEX_APPLICATION_TEMP_FILES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\30D3\30E5\30FCAPEX_APPLICATION_TEMP_FILES\3067\30A2\30AF\30BB\30B9\3067\304D\308B\4E00\6642\7684\306A\5834\6240\306B\30A2\30C3\30D7\30ED\30FC\30C9\3057\305F\30D5\30A1\30A4\30EB\3092\683C\7D0D\3057\307E\3059\3002&PRODUCT_NAME.\306F\3001<strong>\300C\30D5\30A1\30A4\30EB\3092\30D1\30FC\30B8\3059\308B\30BF\30A4\30DF\30F3\30B0\300D</strong>\306E\9078\629E\306B\5FDC\3058\3066\30BB\30C3\30B7\30E7\30F3\306E\7D42\4E86\6642\307E\305F\306F\30A2\30C3\30D7\30ED\30FC\30C9\30FB\30EA\30AF\30A8\30B9\30C8\306E\7D42\4E86\6642\306B\81EA\52D5\7684\306B\30D5\30A1\30A4\30EB\3092\524A\9664\3057\307E\3059\3002</p>'),
unistr('<p><strong>\300C\8907\6570\30D5\30A1\30A4\30EB\306E\8A31\53EF\300D</strong>\304C<strong>\300C\3044\3044\3048\300D</strong>\306B\8A2D\5B9A\3055\308C\3066\3044\308B\5834\5408\306B\30D5\30A1\30A4\30EB\306B\30A2\30AF\30BB\30B9\3059\308B\306B\306F:</p>'),
'<pre>',
'select *',
'  from apex_application_temp_files',
' where name = :<em>page item name</em>;',
'</pre>',
unistr('<p><strong>\300C\8907\6570\30D5\30A1\30A4\30EB\306E\8A31\53EF\300D</strong>\304C<strong>\300C\306F\3044\300D</strong>\306B\8A2D\5B9A\3055\308C\3066\3044\308B\5834\5408\306B\30D5\30A1\30A4\30EB\306B\30A2\30AF\30BB\30B9\3059\308B\306B\306F:</p>'),
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
'                        p_str => :<em>page item name</em>,',
'                        p_sep => '':'' );',
'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
'          from apex_application_temp_files',
'         where name = l_file_names(i);',
'        -- add code here to store the uploaded file in your own table',
'    end loop;',
'end;',
'</pre>'))
);
